        if not self._path.exists():
            return
        for line in self._path.read_text(encoding="utf-8").splitlines():
            if not line.strip():
                continue
            rec = json.loads(line)
            if rec.get("kind") == "suggestion":
                self._suggestions[rec["summary_id"]] = rec
            elif rec.get("kind") == "decision":
                self._decisions[rec["summary_id"]] = rec

    def _write(self, rec: dict) -> None:
        try:
            self._path.parent.mkdir(parents=True, exist_ok=True)
            with self._path.open("a", encoding="utf-8") as fh:
                fh.write(canonical_json(rec) + "\n")
                fh.flush()
        except OSError as exc:
            raise ApprovalError("approval write failed") from exc

    def add_suggestion(self, rec: dict) -> None:
        with self._lock:
            entry = {"kind": "suggestion", **rec}
            self._write(entry)
            self._suggestions[rec["summary_id"]] = entry

