        "recommendation": {"type": "string", "maxLength": 400},
        "confidence": {"type": "number", "minimum": 0, "maximum": 1},
        "abstain_reason": {"enum": [None, *ABSTAIN_REASONS]},
    },
}
_MODEL_VALIDATOR = jsonschema.Draft202012Validator(MODEL_OUTPUT_SCHEMA)

_TEMPLATE_RE = re.compile(r"\{\{|\}\}|\{%|%\}|\$\{|__[a-z]+__|\{[^{}]*\.__", re.I)
