class _Generator:
    def __init__(self, name: str, version: str):
        self.name, self.version = name, version


DETERMINISTIC = _Generator("deterministic", "1.0.0")
EXTERNAL = _Generator("external-provider", "unknown")


class DeterministicProvider:
    """Default and fallback provider. Builds the summary from validated fields only."""

    def __call__(self, system_prompt: str, data_json: str) -> str:
        ctx = json.loads(data_json)
        s, events, bookings, quality = ctx["shipment"], ctx["events"], ctx["bookings"], ctx["quality"]
        sid = s["shipment_id"]
        status = s.get("status", "")
        sentences = [f"Shipment {sid} is recorded with status '{status}'"]
        if s.get("service_tier"):
            sentences[0] += f" under the '{s['service_tier']}' service tier"
        sentences[0] += "."
        if s.get("promised_at"):
            sentences.append(f"Promised delivery time is {s['promised_at']}.")
        if quality.get("status_legacy"):
            sentences.append("The status value is a legacy value and is flagged for owner review.")
        sentences.append(f"The tracking history holds {len(events)} event(s) in the context.")
        if events:
            last = events[-1]
            if last.get("event_type"):
                sentences.append(f"The latest event is '{last['event_type']}' at {last.get('event_time', 'an unknown time')}.")
            else:
                sentences.append("The latest event type is outside the declared domain.")
        statuses = sorted({b.get("status", "") for b in bookings if b.get("status")})
        sentences.append(f"Carrier bookings: {len(bookings)}" + (f" with status {', '.join(statuses)}." if statuses else "."))
        if any(b.get("compensation_required") is True for b in bookings):
            sentences.append("At least one booking is marked as requiring compensation review.")
        summary = " ".join(sentences)[:1200]

        compensation = any(b.get("compensation_required") is True for b in bookings)
        if status in ("exception", "failed", "manual_hold"):
            recommendation = (f"Refer shipment {sid} to the dispatcher for review of the '{status}' state. "
                              "No action has been taken by the system.")
        elif compensation:
            recommendation = (f"Refer the compensation requirement on shipment {sid} to the dispatcher. "
