def clean_text(value) -> tuple[str, bool]:
    """Strip control characters; replace template syntax by a marker. Returns (text, removed)."""
    text = "" if value is None else str(value)
    text = _CONTROL_RE.sub(" ", text).strip()
    if _TEMPLATE_RE.search(text):
        return "[removed]", True
    return text[:MAX_VALUE_CHARS], False


def _estimate_tokens(text: str) -> int:
    return math.ceil(len(text) / 4)


def _encode_data(ctx: dict) -> str:
    raw = json.dumps(ctx, sort_keys=True, ensure_ascii=False)
    # Escaped so a value cannot close or open markup in the data block.
    return raw.replace("<", "\\u003c").replace(">", "\\u003e")


def _sha256_text(text: str) -> str:
