def _valid_or_legacy(policy: Policy, entity: str, field: str, value: str, domain: str) -> tuple[str | None, bool]:
    """Return (value or None, legacy_flag). Out-of-domain values are dropped, not replaced."""
    if value in policy.domain(domain):
        return value, False
    if value in LEGACY_TOLERATED.get(f"{entity}.{field}", set()):
        return value, True
    return None, False


def build_context(*, policy: Policy, shipment: dict, events: list, bookings: list,
                  persona: str, purpose: str, counters: Counter) -> tuple[dict, list, str | None]:
    """Reduce the record to allow-listed, sanitised fields. Returns (context, sources, abstain_reason)."""
    def visible(entity: str, field: str) -> bool:
        return policy.ai_field_visible(entity, field)

    def clean(value) -> str:
        text, removed = clean_text(value)
        if removed:
            counters["template_removed"] += 1
        return text

    quality = {"service_tier_invalid": False, "status_legacy": False,
               "invalid_event_types": 0, "legacy_booking_status": 0}

    shipment_ctx: dict = {}
    sources: list[dict] = []
    sid = clean(shipment.get("shipment_id"))
    if visible("shipments", "shipment_id"):
        shipment_ctx["shipment_id"] = sid
    sources.append({"dataset": "shipments", "record_id": sid})

    status_raw = clean(shipment.get("status"))
    status, legacy = _valid_or_legacy(policy, "shipments", "status", status_raw, "shipment_status")
    if status and visible("shipments", "status"):
        shipment_ctx["status"] = status
        quality["status_legacy"] = legacy
    tier = clean(shipment.get("service_tier"))
    if tier and tier not in policy.domain("service_tier") and visible("shipments", "service_tier"):
        quality["service_tier_invalid"] = True
    elif tier and visible("shipments", "service_tier"):
        shipment_ctx["service_tier"] = tier
    promised = clean(shipment.get("promised_at"))
    if promised and visible("shipments", "promised_at"):
        shipment_ctx["promised_at"] = promised
    for flag in ("customs_required", "temperature_controlled"):
        raw = clean(shipment.get(flag)).lower()
        if raw in ("true", "false") and visible("shipments", flag):
            shipment_ctx[flag] = raw == "true"

    missing = [f for f in ("shipment_id", "status", "promised_at") if not clean(shipment.get(f))]
    if missing or status is None:
        return _ctx(shipment_ctx, [], [], quality), sources, "insufficient_context"

    event_ctx: list[dict] = []
    event_sources: list[dict] = []
    if policy.decide(persona, "tracking_events", "read", purpose).allowed:
        for ev in events:
            item: dict = {}
            etype = clean(ev.get("event_type"))
            if etype and etype in policy.domain("tracking_event_type"):
                if visible("tracking_events", "event_type"):
                    item["event_type"] = etype
            elif etype:
                quality["invalid_event_types"] += 1
            etime = clean(ev.get("event_time"))
            if etime and visible("tracking_events", "event_time"):
                item["event_time"] = etime
            try:
                seq = int(float(ev.get("sequence_no") or ""))
            except ValueError:
                seq = None
            if seq is not None and visible("tracking_events", "sequence_no"):
                item["sequence_no"] = seq
            source = clean(ev.get("source_system"))
            if source in policy.domain("source_system") and visible("tracking_events", "source_system"):
                item["source_system"] = source
            event_ctx.append((seq if seq is not None else 10**9, item))
            event_sources.append({"dataset": "tracking_events", "record_id": clean(ev.get("event_id"))})
    event_ctx.sort(key=lambda pair: pair[0])
    event_items = [item for _, item in event_ctx][-MAX_EVENTS_IN_CONTEXT:]

    booking_ctx: list[dict] = []
    booking_sources: list[dict] = []
    if policy.decide(persona, "carrier_bookings", "read", purpose).allowed:
        for bk in bookings:
            item = {}
            bstatus_raw = clean(bk.get("status"))
            bstatus, blegacy = _valid_or_legacy(policy, "carrier_bookings", "status", bstatus_raw, "shipment_status")
            if bstatus and visible("carrier_bookings", "status"):
                item["status"] = bstatus
            if blegacy:
                quality["legacy_booking_status"] += 1
            try:
                item["retry_count"] = int(float(bk.get("retry_count") or ""))
            except ValueError:
                pass
            comp = clean(bk.get("compensation_required")).lower()
            if comp in ("true", "false"):
                item["compensation_required"] = comp == "true"
            booking_ctx.append(item)
            booking_sources.append({"dataset": "carrier_bookings", "record_id": clean(bk.get("booking_id"))})

    active = [b for b in bookings if clean(b.get("status")) not in ACTIVE_EXCLUDED_BOOKING]
    conflict = len(active) > 1
    if not event_items and not booking_ctx:
        return _ctx(shipment_ctx, [], [], quality), sources, "insufficient_context"

    sources.extend(event_sources[-MAX_EVENTS_IN_CONTEXT:])
    sources.extend(booking_sources)
    context = _ctx(shipment_ctx, event_items, booking_ctx, quality)
    if conflict:
        # Sources conflict (more than one active booking, BR-05): abstain.
        return context, sources, "low_confidence"
