            bstatus_raw = clean(bk.get("status"))
            bstatus, blegacy = _valid_or_legacy(policy, "carrier_bookings", "status", bstatus_raw, "shipment_status")
            if bstatus and visible("carrier_bookings", "status"):
                item["status"] = bstatus
            if blegacy:
                quality["legacy_booking_status"] += 1
            try:
                item["retry_count"] = int(float(bk.get("retry_count") or ""))
            except ValueError:
                pass
            comp = clean(bk.get("compensation_required")).lower()
            if comp in ("true", "false"):
                item["compensation_required"] = comp == "true"
            booking_ctx.append(item)
            booking_sources.append({"dataset": "carrier_bookings", "record_id": clean(bk.get("booking_id"))})

    active = [b for b in bookings if clean(b.get("status")) not in ACTIVE_EXCLUDED_BOOKING]
    conflict = len(active) > 1
    if not event_items and not booking_ctx:
        return _ctx(shipment_ctx, [], [], quality), sources, "insufficient_context"

    sources.extend(event_sources[-MAX_EVENTS_IN_CONTEXT:])
    sources.extend(booking_sources)
    context = _ctx(shipment_ctx, event_items, booking_ctx, quality)
    if conflict:
        # Sources conflict (more than one active booking, BR-05): abstain.
        return context, sources, "low_confidence"
    # Keep the prompt inside the context budget: drop the oldest events first.
    while _estimate_tokens(_encode_data(context)) > MAX_CONTEXT_TOKENS and context["events"]:
        context["events"].pop(0)
        counters["events_trimmed"] += 1
    return context, sources, None


def _ctx(shipment_ctx, events, bookings, quality) -> dict:
    return {"shipment": shipment_ctx, "events": events, "bookings": bookings, "quality": quality}


def parse_model_output(raw) -> dict:
    if not isinstance(raw, str):
        raise SchemaViolation("provider returned a non-text value")
    try:
        obj = json.loads(raw)
    except ValueError as exc:
        raise SchemaViolation("provider output is not JSON") from exc
    try:
        _MODEL_VALIDATOR.validate(obj)
    except jsonschema.ValidationError as exc:
        raise SchemaViolation("provider output does not match the output schema") from exc
    if obj.get("abstain_reason") is None and (not obj["summary"].strip() or not obj["recommendation"].strip()):
        raise SchemaViolation("summary and recommendation are required when not abstaining")
    return obj


def output_guardrail_violations(obj: dict, forbidden_values: list[str]) -> list[str]:
    violations = []
    texts = [obj.get("summary") or "", obj.get("recommendation") or ""]
    for text in texts:
        if _OUTPUT_FORBIDDEN_RE.search(text):
            violations.append("forbidden_pattern")
        if _LEAK_RE.search(text):
            violations.append("identifier_leak")
        if any(v and v in text for v in forbidden_values):
            violations.append("forbidden_value")
    return violations


def _config_hash(gen: _Generator) -> str:
    return _sha256_text(f"{PROMPT_SHA}|{gen.name}|{gen.version}|{MAX_RECORD_TOKENS}")


def _assemble(*, correlation_id, gen, summary, recommendation, confidence, abstained, abstain_reason,
              guardrail_status, generated_by, fallback_reason, sources, token_estimate) -> dict:
    body = {
        "summary_id": "sum_" + uuid.uuid4().hex,
        "model": gen.name,
        "model_version": gen.version,
        "prompt_version": PROMPT_VERSION,
        "summary": summary,
        "recommendation": recommendation,
        "abstained": abstained,
        "abstain_reason": abstain_reason,
        "guardrail_status": guardrail_status,
        "generated_by": generated_by,
        "fallback_reason": fallback_reason,
        "source_count": len(sources),
        "token_estimate": token_estimate,
        "requires_human_approval": True,
        "correlation_id": correlation_id,
        "token_source": "estimate",
        "confidence": confidence,
        "sources": sources,
        "config_hash": _config_hash(gen),
    }
    errors = sorted(_OUTPUT_VALIDATOR.iter_errors(body), key=lambda e: list(e.path))
    if errors:
        raise GatewayError("summary output failed schema validation")
    return body


def run_summary(*, shipment: dict, events: list, bookings: list, policy: Policy,
                correlation_id: str, provider=None, persona: str = "ai_agent",
                purpose: str = "exception_summary") -> dict:
    """Run the guardrailed summary. Raises PolicyDenied, or GatewayError on an internal fault."""
    decision = policy.decide(persona, "shipments", "read", purpose)
    if not decision.allowed:
        raise PolicyDenied(decision.rule)

    counters: Counter = Counter()
    context, sources, pre_abstain = build_context(
        policy=policy, shipment=shipment, events=events, bookings=bookings,
        persona=persona, purpose=purpose, counters=counters)
    if pre_abstain:
        # No generation happened, so there is nothing to guard.
        return _assemble(correlation_id=correlation_id, gen=DETERMINISTIC, summary=None, recommendation=None,
                         confidence=None, abstained=True, abstain_reason=pre_abstain,
                         guardrail_status="not_applicable", generated_by="deterministic",
                         fallback_reason=None, sources=sources, token_estimate=0)

    data_json = _encode_data(context)
    token_estimate = _estimate_tokens(PROMPT_TEXT + data_json)
    forbidden_values = [v for v in [shipment.get("customer_id", "")] if v]
    result = None          # (summary, recommendation, confidence)
    gen = DETERMINISTIC
    generated_by = "deterministic"
    fallback_reason = None
    guardrail_status = "enforced"
    abstain_reason = None

    if provider is not None:
        try:
            obj = parse_model_output(provider(PROMPT_TEXT, data_json))
            if obj.get("abstain_reason"):
                abstain_reason = obj["abstain_reason"]
                gen, generated_by = EXTERNAL, "model"
            elif output_guardrail_violations(obj, forbidden_values):
                guardrail_status, fallback_reason = "blocked", "guardrail_blocked"
            elif obj["confidence"] < CONFIDENCE_FLOOR:
                fallback_reason = "low_confidence"
            else:
                result = (obj["summary"], obj["recommendation"], obj["confidence"])
                gen, generated_by = EXTERNAL, "model"
        except ConnectionError:
            fallback_reason = "provider_unavailable"
        except SchemaViolation:
            fallback_reason = "schema_violation"
        except Exception:  # noqa: BLE001 - any provider fault is untrusted and falls back
            fallback_reason = "provider_error"
        if fallback_reason:
            generated_by = "fallback"

    if result is None and abstain_reason is None:
        try:
            obj = parse_model_output(DeterministicProvider()(PROMPT_TEXT, data_json))
        except Exception as exc:  # noqa: BLE001
            raise GatewayError("deterministic provider failed") from exc
        if output_guardrail_violations(obj, forbidden_values):
            raise GatewayError("deterministic output failed the guardrail")
        if obj["confidence"] < CONFIDENCE_FLOOR:
            abstain_reason = "low_confidence"
        else:
            result = (obj["summary"], obj["recommendation"], obj["confidence"])

    if abstain_reason is not None:
        return _assemble(correlation_id=correlation_id, gen=gen, summary=None, recommendation=None,
                         confidence=None, abstained=True, abstain_reason=abstain_reason,
                         guardrail_status=guardrail_status, generated_by=generated_by,
                         fallback_reason=fallback_reason, sources=sources, token_estimate=token_estimate)
    summary, recommendation, confidence = result
    return _assemble(correlation_id=correlation_id, gen=gen, summary=summary, recommendation=recommendation,
                     confidence=confidence, abstained=False, abstain_reason=None,
                     guardrail_status=guardrail_status, generated_by=generated_by,
                     fallback_reason=fallback_reason, sources=sources, token_estimate=token_estimate)


def input_hash(shipment: dict, events: list, bookings: list) -> str:
    raw = json.dumps({"shipment": shipment, "events": events, "bookings": bookings},
                     sort_keys=True, ensure_ascii=False)
    return _sha256_text(raw)
