class RateLimiter:
    """Sliding one-minute window per subject (AI endpoint, 30/min default [ASM])."""

    def __init__(self, per_minute: int):
        self._limit = per_minute
        self._hits: dict[str, list[float]] = {}
        self._lock = threading.Lock()

    def allow(self, subject: str) -> bool:
        now = time.monotonic()
        with self._lock:
            hits = [t for t in self._hits.get(subject, []) if now - t < RATE_WINDOW_SECONDS]
            if len(hits) >= self._limit:
                self._hits[subject] = hits
                return False
            hits.append(now)
            self._hits[subject] = hits
            return True


